6	/** Width of each floating scroll button. */
7	export const SCROLL_BUTTON_WIDTH = 32;
8	/** Distance scrolled by one scroll button click. */
9	export const SCROLL_STEP = 200;
10	/** Sub-pixel tolerance used when deciding whether the scroll end has been reached. */
11	const SCROLL_EDGE_TOLERANCE = 1;
12	
13	interface HorizontalScrollAreaProps {
