22	const NO_SCROLL: ScrollState = { canScrollEnd: false, canScrollStart: false };
23	
24	/** Reads overflow and scroll-direction availability from the scroller and its content. */
25	function measureScrollState(scroller: HTMLElement, content: HTMLElement): ScrollState {
26	    if (content.scrollWidth <= scroller.clientWidth) return NO_SCROLL;
27	    const canScrollStart = scroller.scrollLeft > SCROLL_EDGE_TOLERANCE;
28	    const canScrollEnd = scroller.scrollLeft + scroller.clientWidth < scroller.scrollWidth - SCROLL_EDGE_TOLERANCE;
29	
30	    return { canScrollEnd, canScrollStart };
31	}
32	
33	function isSameScrollState(left: ScrollState, right: ScrollState) {
34	    return left.canScrollEnd === right.canScrollEnd && left.canScrollStart === right.canScrollStart;
35	}
